render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(word = cfg$x, freq = cfg$y), c("word", "freq")); chart_open_device(cfg$outputPath, cfg$format); wordcloud::wordcloud(words = as.character(data[[cfg$x]]), freq = data[[cfg$y]], min.freq = 1, random.order = FALSE, colors = c(cfg$color %||% "#0A84FF", "#FF6B35", "#475569")); title(cfg$title %||% "关键词词云"); grDevices::dev.off(); cfg$outputPath }
